// Only the execution of the latest message from this number continues; the others end silently
const current = $('Verify Twilio signature').first().json;
const rows = $input.all().map(i => i.json).filter(r => r.message_id);
if (!rows.length || rows[rows.length - 1].message_id !== current.message_id) {
  return [];
}

return [{ json: {
  ...current,
  text: rows.map(r => r.text).join('\n'),
  message_count: rows.length,
  last_buffer_id: Math.max(...rows.map(r => Number(r.id)))
} }];

