// Twilio signs every webhook: base64(HMAC-SHA1(Auth Token, URL + every POST parameter name and value, sorted by name)).
// Both values are filled in at import (scripts/reload-workflows.sh); while they are placeholders every request is rejected.
const crypto = require('crypto');
const AUTH_TOKEN = '__TWILIO_AUTH_TOKEN__';
const WEBHOOK_URL = '__TWILIO_WEBHOOK_URL__';

const { headers = {}, body = {} } = $input.first().json;
const signed = WEBHOOK_URL + Object.keys(body).sort().map(key => key + body[key]).join('');
const expected = crypto.createHmac('sha1', AUTH_TOKEN).update(signed, 'utf8').digest('base64');
const received = String(headers['x-twilio-signature'] || '');
const configured = !AUTH_TOKEN.startsWith('__') && !WEBHOOK_URL.startsWith('__');
const valid = configured && received.length === expected.length
  && crypto.timingSafeEqual(Buffer.from(received), Buffer.from(expected));

return [{ json: {
  valid,
  // "+15551234567" (SMS) or "whatsapp:+15551234567" (Twilio WhatsApp): replies go back to the same address
  from: String(body.From || ''),
  to: String(body.To || ''),
  phone: String(body.From || '').replace(/\D/g, ''),
  message_id: String(body.MessageSid || ''),
  text: String(body.Body || '').trim()
} }];
